		paddingVertical: Spacing.two,
		borderRadius: Spacing.five,
		justifyContent: "center",
		gap: Spacing.one,
		alignItems: "center",
	},
	sectionsWrapper: {
		gap: Spacing.five,
		paddingHorizontal: Spacing.four,
		paddingTop: Spacing.three,
	},
	collapsibleContent: {
		alignItems: "center",
	},
	imageTutorial: {
		width: "100%",
		aspectRatio: 296 / 171,
		borderRadius: Spacing.three,
		marginTop: Spacing.two,
	},
	imageReact: {
		width: 100,
		height: 100,
		alignSelf: "center",
	},
});

