						<>
							<Input
								label="Name"
								placeholder="Your name"
								value={name}
								onChangeText={(text) => {
									setName(text);
									setApiError("");
								}}
								autoCorrect={false}
								editable={!isSubmitting}
							/>
							<Input
								label="Email"
								placeholder="m@example.com"
								value={email}
								onChangeText={(text) => {
									setEmail(text);
									setApiError("");
								}}
								autoCapitalize="none"
								autoCorrect={false}
								keyboardType="email-address"
								textContentType="username"
								editable={!isSubmitting}
							/>
							<Input
								label="Password"
								placeholder="At least 8 characters"
								value={password}
								onChangeText={(text) => {
									setPassword(text);
									setApiError("");
								}}
								secureTextEntry
								textContentType="newPassword"
								editable={!isSubmitting}
							/>
							{apiError ? (
								<ThemedText style={[styles.error, { color: theme.destructive }]}>
									{apiError}
								</ThemedText>
							) : null}
							<Button fullWidth loading={isSubmitting} onPress={onSubmit}>
								{isSubmitting ? "Signing up..." : "Sign Up"}
							</Button>
						</>
					)}

					{hasSocialOptions && (
						<>
							{isEmailPasswordEnabled && <Separator label="Or continue with" />}
							{!isEmailPasswordEnabled && apiError ? (
								<ThemedText style={[styles.error, { color: theme.destructive }]}>
									{apiError}
								</ThemedText>
							) : null}
							<Button
								variant="outline"
								fullWidth
								loading={isGithubLoading}
								disabled={isSubmitting}
								onPress={() => handleSocialSignIn("github")}
							>
								{isGithubLoading ? "Signing in..." : "Sign up with GitHub"}
							</Button>
							<Button
								variant="outline"
								fullWidth
								loading={isGoogleLoading}
								disabled={isSubmitting}
								onPress={() => handleSocialSignIn("google")}
							>
								{isGoogleLoading ? "Signing in..." : "Sign up with Google"}
							</Button>
						</>
					)}

					<ThemedText type="small" style={styles.footer}>
						Already have an account?{" "}
						<Link href="/sign-in" style={{ color: theme.primary }}>
							Sign In
						</Link>
					</ThemedText>
				</CardContent>
			</Card>
		</AuthScreen>
	);
}

const styles = StyleSheet.create({
